// ── Config: inject secrets + extract webhook body ──────────────────────
const supabaseUrl = "YOUR_SUPABASE_URL";
const supabaseKey = "YOUR_SUPABASE_SERVICE_ROLE_KEY";
const openaiKey   = "YOUR_OPENAI_API_KEY";

const body = $input.first().json.body || $input.first().json;

return [{ json: { supabaseUrl, supabaseKey, openaiKey, ...body } }];

// ── Build the prompt for the AI agent ─────────────────────────────────
const cfg = $('Config').first().json;
const expItems = $input.all();
const first = expItems[0]?.json;
const experiences = Array.isArray(first) ? first : expItems.map(i => i.json).filter(e => e && e.title);

const { userId, docType, jobDescription, documentId, templateId, templateHtml, profile, openaiKey, supabaseUrl, supabaseKey } = cfg;

// Format experiences as a readable text block for the AI
const expText = experiences.length === 0
  ? '(Nessuna esperienza disponibile)'
  : experiences.map(e => {
      const range = e.is_current
        ? `${e.start_date || '?'} – Presente`
        : `${e.start_date || '?'} – ${e.end_date || '?'}`;
      const skills = (e.skills || []).join(', ');
      return `ID:${e.id} | [${(e.type||'work').toUpperCase()}] ${e.title} @ ${e.organization||'N/A'} (${range})${e.location ? ' · ' + e.location : ''}\n  Descrizione: ${(e.description||'').slice(0,400)}\n  Competenze: ${skills||'N/A'}`;
    }).join('\n\n');

const profileText = profile
  ? `Nome: ${profile.fullName||''}\nRuolo: ${profile.headline||''}\nCittà: ${profile.city||''}\nTelefono: ${profile.phone||''}\nLinkedIn: ${profile.linkedinUrl||''}\nPortfolio: ${profile.portfolioUrl||''}`
  : '(Profilo non disponibile)';

const systemPrompt = `Sei un esperto career coach italiano specializzato in CV ATS-friendly.
Hai ricevuto le esperienze di un candidato e una Job Description.

IL TUO COMPITO:
1. Seleziona le esperienze più rilevanti per la Job Description (max 4 esperienze lavorative, max 3 education)
2. Per ogni esperienza selezionata, scrivi una descrizione ottimizzata (2-4 frasi, keywords dalla JD, risultati concreti)
3. Genera un profilo professionale di 3-4 righe (profile_summary)
4. Estrai una lista di competenze tecniche rilevanti per la JD (max 12)
5. Restituisci SOLO un JSON valido, senza markdown, senza spiegazioni.

STRUTTURA JSON RICHIESTA:
{
  "profile_summary": "stringa",
  "experiences": [
    {
      "title": "stringa",
      "organization": "stringa",
      "location": "stringa o null",
      "date_range": "MMM YYYY – MMM YYYY o Presente",
      "description": "paragrafo ottimizzato",
      "skills": ["skill1", "skill2"]
    }
  ],
  "education": [
    {
      "title": "stringa",
      "organization": "stringa",
      "date_range": "stringa",
      "description": "stringa o null"
    }
  ],
  "certifications": [
    {
      "title": "stringa",
      "organization": "stringa",
      "date_range": "stringa"
    }
  ],
  "skills": ["skill1", "skill2", "..."],
  "languages": [
    { "language": "Italiano", "level": "Madrelingua" }
  ]
}`;

const userPrompt = `PROFILO CANDIDATO:\n${profileText}\n\nESPERIENZE DISPONIBILI:\n${expText}\n\nJOB DESCRIPTION:\n${jobDescription}\n\nRestituisci il JSON strutturato come richiesto.`;

return [{ json: {
  userId, docType, jobDescription, documentId,
  templateId, templateHtml, profile,
  openaiKey, supabaseUrl, supabaseKey,
  systemPrompt, userPrompt
} }];

// ── Fill Template: parse AI JSON and inject into HTML template ─────────
const cfg = $('Config').first().json;
const buildData = $('🧠 Build AI Prompt').first().json;
const aiRaw = $input.first().json.choices[0].message.content;

// 1. Parse AI JSON
let cvData;
try {
  const cleaned = aiRaw.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '').trim();
  cvData = JSON.parse(cleaned);
} catch (e) {
  throw new Error('AI output is not valid JSON: ' + aiRaw.slice(0, 300));
}

// 2. Profile fields
const profile = buildData.profile || {};
const fullName = (profile.fullName || cvData.full_name || 'Nome Cognome').trim();
const nameParts = fullName.split(' ');
const firstName = nameParts[0] || '';
const lastName  = nameParts.slice(1).join(' ') || '';
const initials  = nameParts.map(p => p[0]||'').join('').toUpperCase().slice(0,2);
const tid = buildData.templateId || 'modern';

// 3. Block builders
function experienceEntry(e, t) {
  const dr = e.date_range || '';
  const loc = e.location ? ` · ${e.location}` : '';
  const desc = e.description ? `<div class="entry-desc">${e.description}</div>` : '';
  const tags = (e.skills||[]).length ? `<div class="entry-tags">${(e.skills||[]).map(s=>`<span class="entry-tag">${s}</span>`).join('')}</div>` : '';
  const ctags = (e.skills||[]).length ? `<div class="entry-card-tags">${(e.skills||[]).map(s=>`<span class="entry-card-tag">${s}</span>`).join('')}</div>` : '';
  if (t === 'minimal') return `<div class="entry"><div class="entry-header"><div class="entry-title">${e.title}</div><div class="entry-date">${dr}</div></div><div class="entry-org">${e.organization||''}${loc}</div>${desc}</div>`;
  if (t === 'creative') return `<div class="entry-card"><div class="entry-card-top"><div class="entry-card-title">${e.title}</div><div class="entry-card-date">${dr}</div></div><div class="entry-card-org">${e.organization||''}${loc}</div>${e.description?`<div class="entry-card-desc">${e.description}</div>`:''} ${ctags}</div>`;
  return `<div class="entry"><div class="entry-left"><div class="entry-bullet"></div><div class="entry-line"></div></div><div class="entry-right"><div class="entry-meta">${dr}${loc}</div><div class="entry-title">${e.title}</div><div class="entry-org">${e.organization||''}</div>${desc}${tags}</div></div>`;
}

function educEntry(e, t) {
  const dr = e.date_range || '';
  const desc = e.description ? `<div class="entry-desc">${e.description}</div>` : '';
  if (t === 'minimal') return `<div class="entry"><div class="entry-header"><div class="entry-title">${e.title}</div><div class="entry-date">${dr}</div></div><div class="entry-org">${e.organization||''}</div>${desc}</div>`;
  if (t === 'creative') return `<div class="entry-card"><div class="entry-card-top"><div class="entry-card-title">${e.title}</div><div class="entry-card-date">${dr}</div></div><div class="entry-card-org">${e.organization||''}</div>${desc?`<div class="entry-card-desc">${e.description}</div>`:''}</div>`;
  return `<div class="entry"><div class="entry-left"><div class="entry-bullet"></div><div class="entry-line"></div></div><div class="entry-right"><div class="entry-meta">${dr}</div><div class="entry-title">${e.title}</div><div class="entry-org">${e.organization||''}</div>${desc}</div></div>`;
}

function skillsHtml(skills, t) {
  if (!skills || !skills.length) return '';
  if (t === 'modern')   return skills.map(s=>`<span class="skill-tag">${s}</span>`).join('');
  if (t === 'creative') return skills.map(s=>`<span class="skill-pill">${s}</span>`).join('');
  return skills.map(s=>`<div class="skill-line">${s}</div>`).join('');
}

function langPercent(lv) { return ({A1:15,A2:28,B1:45,B2:62,C1:80,C2:95,Native:100,Madrelingua:100})[lv]||50; }
function langsHtml(langs, t) {
  if (!langs || !langs.length) return '';
  if (t === 'minimal') return langs.map(l=>`<div class="lang-item"><div class="lang-name-row"><span class="lang-name">${l.language}</span><span class="lang-level">${l.level||''}</span></div><div class="lang-bar"><div class="lang-bar-fill" style="width:${langPercent(l.level)}%"></div></div></div>`).join('');
  return langs.map(l=>`<div class="side-item"><div class="side-item-label">${l.language}</div><div class="side-item-sub">${l.level||''}</div></div>`).join('');
}

// 4. Build all blocks
const experiencesHtml    = (cvData.experiences    ||[]).map(e=>experienceEntry(e,tid)).join('\n');
const educationHtml      = (cvData.education      ||[]).map(e=>educEntry(e,tid)).join('\n');
const certificationsHtml = (cvData.certifications ||[]).map(e=>educEntry(e,tid)).join('\n');
const skillsList         = skillsHtml(cvData.skills, tid);
const languagesHtml      = langsHtml(cvData.languages, tid);

// 5. Replace placeholders
const map = {
  '{{full_name}}':           fullName,
  '{{first_name}}':          firstName,
  '{{last_name}}':           lastName,
  '{{initials}}':            initials,
  '{{headline}}':            profile.headline     || '',
  '{{city}}':                profile.city         || '',
  '{{phone}}':               profile.phone        || '',
  '{{linkedin_url}}':        profile.linkedinUrl  || '',
  '{{portfolio_url}}':       profile.portfolioUrl || '',
  '{{avatar_url}}':          profile.avatarUrl    || '',
  '{{profile_summary}}':     cvData.profile_summary || '',
  '{{experiences_html}}':    experiencesHtml,
  '{{education_html}}':      educationHtml,
  '{{certifications_html}}': certificationsHtml,
  '{{skills_list}}':         skillsList,
  '{{skills_section_html}}': skillsList,
  '{{languages_html}}':      languagesHtml,
};

let html = buildData.templateHtml || '';
for (const [k, v] of Object.entries(map)) {
  html = html.split(k).join(v || '');
}
// Remove unfilled Handlebars-style blocks
html = html
  .replace(/\{\{#if [^}]+\}\}[\s\S]*?\{\{\/if\}\}/g, '')
  .replace(/\{\{[^}]+\}\}/g, '');

const filename = `cv-${buildData.userId}-${Date.now()}.html`;

return [{ json: {
  userId: buildData.userId,
  documentId: buildData.documentId,
  supabaseUrl: cfg.supabaseUrl,
  supabaseKey: cfg.supabaseKey,
  html,
  filename,
} }];

const data = $('📄 Fill Template').first().json;
const pdfUrl = data.supabaseUrl + '/storage/v1/object/public/documents/' + data.filename;
return [{ json: { ...data, pdf_url: pdfUrl } }];
